// Prompt 2 parser + Supabase callback body builder — fail-soft version
//
// Make Code module inputs:
//   rawInput             = Claude Prompt 2 response (string or object)
//   jobId                = original webhook job_id
//   providerExecutionId  = Make execution ID (optional)
//   providerExecutionUrl = Make execution URL (optional)
//   inputTokens          = Prompt 2 input tokens (optional)
//   outputTokens         = Prompt 2 output tokens (optional)
//
// Design rule: this module NEVER throws on a bad model response.
// A thrown error kills the Make execution before the Supabase callback
// fires, which strands the job in "processing" forever. Instead we always
// build a callback body — with status "completed" on a clean parse, or
// "needs_review" when the response was not usable JSON.

// ---------------------------------------------------------------------
// 1. Normalize the provider response down to plain text
// ---------------------------------------------------------------------

function extractText(value) {
    if (value === null || value === undefined) return "";
    if (typeof value === "string") return value;
    if (typeof value !== "object") return String(value);

    if (typeof value.text === "string") return value.text;
    if (typeof value.content === "string") return value.content;

    // Anthropic Messages API: content is an array of blocks. With extended
    // thinking on, block 0 is a thinking block with no .text — so collect
    // every text block instead of assuming index 0.
    if (Array.isArray(value.content)) {
        var parts = [];
        for (var i = 0; i < value.content.length; i++) {
            var block = value.content[i];
            if (block && typeof block.text === "string") {
                parts.push(block.text);
            }
        }
        if (parts.length) return parts.join("\n");
    }

    if (
        value.choices &&
        value.choices[0] &&
        value.choices[0].message &&
        typeof value.choices[0].message.content === "string"
    ) {
        return value.choices[0].message.content;
    }

    return JSON.stringify(value);
}

var rawText = String(extractText(input.rawInput) || "").trim();

// ---------------------------------------------------------------------
// 2. Pull out the scratchpad (optional, may appear before or after JSON)
// ---------------------------------------------------------------------

var scratchpad = null;
var scratchpadMatch = rawText.match(/<scratchpad>([\s\S]*?)<\/scratchpad>/i);

if (scratchpadMatch) {
    scratchpad = scratchpadMatch[1].trim();
}

var body = rawText.replace(/<scratchpad>[\s\S]*?<\/scratchpad>/gi, "").trim();

// ---------------------------------------------------------------------
// 3. Collect every plausible JSON candidate, best-first
// ---------------------------------------------------------------------

// Returns every balanced top-level slice bounded by openChar/closeChar,
// skipping over anything inside a JSON string literal.
function findBalanced(text, openChar, closeChar) {
    var results = [];
    var depth = 0;
    var start = -1;
    var inString = false;
    var escaped = false;

    for (var i = 0; i < text.length; i++) {
        var c = text.charAt(i);

        if (escaped) { escaped = false; continue; }
        if (c === "\\" && inString) { escaped = true; continue; }
        if (c === '"') { inString = !inString; continue; }
        if (inString) continue;

        if (c === openChar) {
            if (depth === 0) start = i;
            depth++;
        } else if (c === closeChar) {
            if (depth > 0) {
                depth--;
                if (depth === 0 && start !== -1) {
                    results.push(text.substring(start, i + 1));
                    start = -1;
                }
            }
        }
    }

    return results;
}

function collectCandidates(text) {
    var candidates = [];
    var seen = {};

    function push(candidate) {
        if (!candidate) return;
        var trimmed = candidate.trim();
        if (!trimmed || seen[trimmed]) return;
        seen[trimmed] = true;
        candidates.push(trimmed);
    }

    // a) Contents of every fenced code block (```json ... ``` or ``` ... ```)
    var fenceRe = /```[ \t]*([a-zA-Z0-9_-]*)[ \t]*\r?\n([\s\S]*?)```/g;
    var fence;
    while ((fence = fenceRe.exec(text)) !== null) {
        push(fence[2]);
    }

    // b) Balanced object / array slices anywhere in the text
    var stripped = text.replace(/```[\s\S]*?```/g, " ");
    var objects = findBalanced(stripped, "{", "}");
    var arrays = findBalanced(stripped, "[", "]");
    for (var i = 0; i < objects.length; i++) push(objects[i]);
    for (var j = 0; j < arrays.length; j++) push(arrays[j]);

    // c) The whole body, in case it is already bare JSON
    push(text);

    return candidates;
}

// ---------------------------------------------------------------------
// 4. Parse, with repairs applied only as escalating fallbacks
// ---------------------------------------------------------------------

function tryParse(candidate) {
    try {
        return { ok: true, value: JSON.parse(candidate) };
    } catch (error) {
        return { ok: false, error: String(error && error.message) };
    }
}

// Removes trailing commas before } or ]. Safe: the pattern cannot occur
// inside a well-formed string that we would otherwise want to keep.
function repairTrailingCommas(text) {
    return text.replace(/,(\s*[}\]])/g, "$1");
}

// Aggressive: rewrites curly quotes to straight ones. This CAN corrupt
// legitimate quoted prose inside string values, so it runs only after
// every gentler attempt has failed.
function repairSmartQuotes(text) {
    return text
        .replace(/[“”]/g, '"')
        .replace(/[‘’]/g, "'");
}

function parseFirstUsable(text) {
    var candidates = collectCandidates(text);
    var lastError = null;

    var repairs = [
        function (t) { return t; },
        repairTrailingCommas,
        function (t) { return repairSmartQuotes(repairTrailingCommas(t)); }
    ];

    for (var r = 0; r < repairs.length; r++) {
        for (var c = 0; c < candidates.length; c++) {
            var attempt = tryParse(repairs[r](candidates[c]));

            if (attempt.ok) {
                var v = attempt.value;
                // Accept objects and arrays; reject bare scalars, which are
                // almost always a fragment we matched by accident.
                if (v !== null && typeof v === "object") {
                    return {
                        ok: true,
                        value: v,
                        repairLevel: r,
                        candidateIndex: c
                    };
                }
            } else {
                lastError = attempt.error;
            }
        }
    }

    return { ok: false, error: lastError };
}

var parsed = parseFirstUsable(body);

// ---------------------------------------------------------------------
// 5. Build the callback payload — always, parsed or not
// ---------------------------------------------------------------------

function safeInteger(value) {
    var number = Number(value || 0);
    return isFinite(number) && number >= 0 ? Math.floor(number) : 0;
}

var jobId = String(input.jobId || "").trim();

var callbackPayload = {
    job_id: jobId,
    status: parsed.ok ? "completed" : "needs_review",
    provider_execution_id: String(input.providerExecutionId || "").trim(),
    provider_execution_url: String(input.providerExecutionUrl || "").trim(),
    extracted_content: parsed.ok ? parsed.value : null,
    raw_extracted_text: rawText,
    scratchpad: scratchpad,
    input_tokens: safeInteger(input.inputTokens),
    output_tokens: safeInteger(input.outputTokens)
};

// Diagnostics only present when something needed attention.
var warnings = [];

if (!rawText) {
    warnings.push("Claude Prompt 2 returned no text");
}

if (!jobId) {
    warnings.push("Missing original webhook jobId");
}

if (!parsed.ok && rawText) {
    warnings.push(
        "No parseable JSON object in the response" +
        (parsed.error ? " (" + parsed.error + ")" : "")
    );
}

if (parsed.ok && parsed.repairLevel > 0) {
    warnings.push(
        "JSON parsed only after repair level " + parsed.repairLevel +
        " — the model's raw output was malformed"
    );
}

if (warnings.length) {
    callbackPayload.parse_warnings = warnings;
}

return {
    callbackBody: JSON.stringify(callbackPayload),
    json: parsed.ok ? JSON.stringify(parsed.value) : null,
    scratchpad: scratchpad,
    parseOk: parsed.ok,
    // Route on this in Make: 0 = clean, 1+ = send to a review branch.
    warningCount: warnings.length
};
